// Doubly linked order with sentinel keys outside the generated key domain.
function lru_work(capacity, operations)
{
    let values = {}
    let previous = {-2: -1}
    let next = {-1: -2}
    let checksum = 0
    let seed = 12345
    for (let op in 0 to operations) {
        seed = (seed * 1103515245 + 12345) % 2147483648
        let key = seed % 256
        let reading = seed % 10 < 7
        let present = key in values
        if (present) {
            let before = previous[key]
            let after = next[key]
            next[before] = after
            previous[after] = before
        } elif (not reading) {
            if (values.len() >= capacity) {
                let evicted = next[-1]
                let after = next[evicted]
                next[-1] = after
                previous[after] = -1
                delete(values, evicted)
                delete(previous, evicted)
                delete(next, evicted)
                checksum = checksum - evicted
            }
        }
        if (present or not reading) {
            let tail = previous[-2]
            previous[key] = tail
            next[key] = -2
            next[tail] = key
            previous[-2] = key
            if (reading) {
                checksum = checksum + values[key]
            } else {
                values[key] = key * 3
            }
        }
    }
    return checksum + 0
}

let capacity = 64
let operations = 300000
let started = clock_ns()
let result = lru_work(capacity, operations)
let elapsed = clock_ns() - started
print(result)
print(elapsed)

